verus! {
    fn not_equal(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
        requires
            a.len() == b.len(),
        ensures
            result.len() == a.len(),
            forall|i: nat| (i < a.len() as nat) ==> (result[i] == (a[i] != b[i])),
    {
        let n = a.len() as nat;
        let mut result: Vec<bool> = Vec::new();
        result.resize(n as usize, false); // Initialize result with false

        let mut i: nat = 0;
        while i < n
            invariant
                i <= n,
                result.len() == n as usize,
                forall|j: nat| (j < i) ==> (result[j] == (a[j] != b[j])),
            decreases n - i,
        {
            result[i as usize] = (a[i] != b[i]) as bool; // Compare elements
            i = i + 1; // Move to the next index
        }
        result
    }
}
